skip_unless_full_tests()

# Expected values are SymPy's outputs for the same calls (sympy/calculus/tests/test_util.py and test_singularities.py);
# the rows come from the battery that compares this port with SymPy.

test_that("function_range: fr matches SymPy", {
  expect_identical(.pyrun(local({ x <- Symbol("x"); y <- Symbol("y"); function_range(sin(x), x, Interval(-sym_pi/2, sym_pi/2)) })), "Interval(-1, 1)")
  expect_identical(.pyrun(local({ x <- Symbol("x"); y <- Symbol("y"); function_range(sin(x), x, Interval(0, sym_pi)) })), "Interval(0, 1)")
  expect_identical(.pyrun(local({ x <- Symbol("x"); y <- Symbol("y"); function_range((x + 3)/(x - 2), x, Interval(-5, 5)) })), "Union(Interval(-oo, 2/7), Interval(8/3, oo))")
  expect_identical(.pyrun(local({ x <- Symbol("x"); y <- Symbol("y"); function_range(1/(x^2), x, Interval(-1, 1)) })), "Interval(1, oo)")
  expect_identical(.pyrun(local({ x <- Symbol("x"); y <- Symbol("y"); function_range(exp(x), x, Interval(-1, 1)) })), "Interval(exp(-1), E)")
  expect_identical(.pyrun(local({ x <- Symbol("x"); y <- Symbol("y"); function_range(log(x) - x, x, Reals) })), "Interval(-oo, -1)")
  expect_identical(.pyrun(local({ x <- Symbol("x"); y <- Symbol("y"); function_range(sqrt(3*x - 1), x, Interval(0, 2)) })), "Interval(0, sqrt(5))")
  expect_identical(.pyrun(local({ x <- Symbol("x"); y <- Symbol("y"); function_range(x*(x - 1) - (x^2 - x), x, Reals) })), "{0}")
  expect_identical(.pyrun(local({ x <- Symbol("x"); y <- Symbol("y"); function_range(x*(x - 1) - (x^2 - x) + y, x, Reals) })), "{y}")
  expect_identical(.pyrun(local({ x <- Symbol("x"); y <- Symbol("y"); function_range(sin(x), x, Union(Interval(-5, -3), FiniteSet(4))) })), "Union({sin(4)}, Interval(-sin(3), 1))")
  expect_identical(.pyrun(local({ x <- Symbol("x"); y <- Symbol("y"); function_range(cos(x), x, Interval(-oo, -4)) })), "Interval(-1, 1)")
  expect_identical(.pyrun(local({ x <- Symbol("x"); y <- Symbol("y"); function_range(sin(exp(x)), x, Reals) })), "Interval(-1, 1)")
  expect_identical(.pyrun(local({ x <- Symbol("x"); y <- Symbol("y"); function_range(cos(x), x, EmptySet) })), "EmptySet")
  expect_identical(.pyrun(local({ x <- Symbol("x"); y <- Symbol("y"); function_range(x/sqrt(x^2+1), x, Reals) })), "Interval.open(-1, 1)")
  expect_identical(.pyrun(local({ x <- Symbol("x"); y <- Symbol("y"); function_range(sin(x) + x, x, Reals) })), "Reals")
  expect_identical(.pyrun(local({ x <- Symbol("x"); y <- Symbol("y"); function_range(x + 1/(x^2 + 1), x, Reals) })), "Reals")
  expect_identical(.pyrun(local({ x <- Symbol("x"); y <- Symbol("y"); function_range(exp(x)*(sin(x) - cos(x))/2 - x, x, Reals) })), "ERR NotImplementedError: Unable to find critical points for -x + (sin(x) - cos(x))*exp(x)/2")
  expect_identical(.pyrun(local({ x <- Symbol("x"); y <- Symbol("y"); function_range(log(x), x, Integers) })), "ERR NotImplementedError: Unable to find range for the given domain.")
  expect_identical(.pyrun(local({ x <- Symbol("x"); y <- Symbol("y"); function_range(sin(x)/2, x, Naturals) })), "ERR NotImplementedError: Unable to find range for the given domain.")
  expect_identical(.pyrun(local({ x <- Symbol("x"); y <- Symbol("y"); function_range(x^2, x, Reals) })), "Interval(0, oo)")
  expect_identical(.pyrun(local({ x <- Symbol("x"); y <- Symbol("y"); function_range(x^2, x, Interval(-1, 2)) })), "Interval(0, 4)")
  expect_identical(.pyrun(local({ x <- Symbol("x"); y <- Symbol("y"); function_range(x^3 - 3*x, x, Interval(-2, 2)) })), "Interval(-2, 2)")
  expect_identical(.pyrun(local({ x <- Symbol("x"); y <- Symbol("y"); function_range(1/x, x, Reals) })), "Union(Interval.open(-oo, 0), Interval.open(0, oo))")
  expect_identical(.pyrun(local({ x <- Symbol("x"); y <- Symbol("y"); function_range(1/x, x, Interval(1, oo)) })), "Interval.Lopen(0, 1)")
  expect_identical(.pyrun(local({ x <- Symbol("x"); y <- Symbol("y"); function_range(x^2 - 4*x + 1, x, Interval(0, 5)) })), "Interval(-3, 6)")
  expect_identical(.pyrun(local({ x <- Symbol("x"); y <- Symbol("y"); function_range(exp(-x^2), x, Reals) })), "Interval.Lopen(0, 1)")
  expect_identical(.pyrun(local({ x <- Symbol("x"); y <- Symbol("y"); function_range(cos(x), x, Reals) })), "Interval(-1, 1)")
  expect_identical(.pyrun(local({ x <- Symbol("x"); y <- Symbol("y"); function_range(abs(x), x, Interval(-2, 3)) })), "ERR NotImplementedError: Unable to find critical points for Abs(x)")
  expect_identical(.pyrun(local({ x <- Symbol("x"); y <- Symbol("y"); function_range(x, x, FiniteSet(1, 2, 3)) })), "{1, 2, 3}")
  expect_identical(.pyrun(local({ x <- Symbol("x"); y <- Symbol("y"); function_range(x^2, x, FiniteSet(-1, 1, 2)) })), "{1, 4}")
  expect_identical(.pyrun(local({ x <- Symbol("x"); y <- Symbol("y"); function_range(atan(x), x, Reals) })), "Interval.open(-pi/2, pi/2)")
  expect_identical(.pyrun(local({ x <- Symbol("x"); y <- Symbol("y"); function_range(log(x), x, Interval(1, sym_E)) })), "Interval(0, 1)")
  expect_identical(.pyrun(local({ x <- Symbol("x"); y <- Symbol("y"); function_range(sqrt(x), x, Interval(0, 4)) })), "Interval(0, 2)")
  expect_identical(.pyrun(local({ x <- Symbol("x"); y <- Symbol("y"); function_range(x*exp(-x), x, Interval(0, oo)) })), "Interval.Lopen(0, exp(-1))")
  expect_identical(.pyrun(local({ x <- Symbol("x"); y <- Symbol("y"); function_range(sin(2*x), x, Interval(0, sym_pi/4)) })), "Interval(0, 1)")
  expect_identical(.pyrun(local({ x <- Symbol("x"); y <- Symbol("y"); function_range(x^2/(x^2 + 1), x, Reals) })), "Interval.Ropen(0, 1)")
})

test_that("lcim: lcim matches SymPy", {
  expect_identical(.pyrun(local({ x <- Symbol("x"); y <- Symbol("y"); lcim(list(Rational(1, 2), Integer(2), Integer(3))) })), "6")
  expect_identical(.pyrun(local({ x <- Symbol("x"); y <- Symbol("y"); lcim(list(sym_pi/2, sym_pi/4, sym_pi)) })), "pi")
  expect_identical(.pyrun(local({ x <- Symbol("x"); y <- Symbol("y"); lcim(list(2*sym_pi, sym_pi/2)) })), "2*pi")
  expect_identical(.pyrun(local({ x <- Symbol("x"); y <- Symbol("y"); lcim(list(Integer(1), 2*sym_pi)) })), "None")
  expect_identical(.pyrun(local({ x <- Symbol("x"); y <- Symbol("y"); lcim(list(Integer(2) + 2*sym_E, sym_E/3 + Rational(1, 3), Integer(1) + sym_E)) })), "2 + 2*E")
  expect_identical(.pyrun(local({ x <- Symbol("x"); y <- Symbol("y"); lcim(list(Integer(4), Integer(6))) })), "12")
  expect_identical(.pyrun(local({ x <- Symbol("x"); y <- Symbol("y"); lcim(list(Rational(2, 3), Rational(3, 4))) })), "6")
  expect_identical(.pyrun(local({ x <- Symbol("x"); y <- Symbol("y"); lcim(list(sqrt(Integer(2)), 3*sqrt(Integer(2))/2)) })), "3*sqrt(2)")
  expect_identical(.pyrun(local({ x <- Symbol("x"); y <- Symbol("y"); lcim(list(sym_pi, sym_E)) })), "None")
  expect_identical(.pyrun(local({ x <- Symbol("x"); y <- Symbol("y"); lcim(list(sym_pi/3, 2*sym_pi/5)) })), "2*pi")
  expect_identical(.pyrun(local({ x <- Symbol("x"); y <- Symbol("y"); lcim(list(x, Integer(2))) })), "None")
  expect_identical(.pyrun(local({ x <- Symbol("x"); y <- Symbol("y"); lcim(list(Integer(5))) })), "5")
  expect_identical(.pyrun(local({ x <- Symbol("x"); y <- Symbol("y"); lcim(list(sym_pi)) })), "pi")
})

test_that("is_convex: convex matches SymPy", {
  expect_identical(.pyrun(local({ x <- Symbol("x"); y <- Symbol("y"); is_convex(1/x, x, domain = Interval(0, oo, TRUE, TRUE)) })), "True")
  expect_identical(.pyrun(local({ x <- Symbol("x"); y <- Symbol("y"); is_convex(1/x, x, domain = Interval(-oo, 0)) })), "False")
  expect_identical(.pyrun(local({ x <- Symbol("x"); y <- Symbol("y"); is_convex(x^2, x, domain = Interval(0, oo)) })), "True")
  expect_identical(.pyrun(local({ x <- Symbol("x"); y <- Symbol("y"); is_convex(1/x^3, x, domain = Interval(0, oo, TRUE)) })), "True")
  expect_identical(.pyrun(local({ x <- Symbol("x"); y <- Symbol("y"); is_convex(-1/x^3, x, domain = Interval(-oo, 0, FALSE, TRUE)) })), "True")
  expect_identical(.pyrun(local({ x <- Symbol("x"); y <- Symbol("y"); is_convex(log(x) ,x) })), "False")
  expect_identical(.pyrun(local({ x <- Symbol("x"); y <- Symbol("y"); is_convex(cos(x) + cos(y), x) })), "False")
  expect_identical(.pyrun(local({ x <- Symbol("x"); y <- Symbol("y"); is_convex(exp(x), x) })), "True")
  expect_identical(.pyrun(local({ x <- Symbol("x"); y <- Symbol("y"); is_convex(x^3, x) })), "False")
  expect_identical(.pyrun(local({ x <- Symbol("x"); y <- Symbol("y"); is_convex(x^4, x) })), "True")
  expect_identical(.pyrun(local({ x <- Symbol("x"); y <- Symbol("y"); is_convex(-x^2, x) })), "False")
  expect_identical(.pyrun(local({ x <- Symbol("x"); y <- Symbol("y"); is_convex(x*log(x), x, domain = Interval(0, oo, TRUE, TRUE)) })), "True")
  expect_identical(.pyrun(local({ x <- Symbol("x"); y <- Symbol("y"); is_convex(sqrt(x), x, domain = Interval(0, oo, TRUE, TRUE)) })), "False")
})

test_that("stationary_points: stationary matches SymPy", {
  expect_identical(.pyrun(local({ x <- Symbol("x"); y <- Symbol("y"); stationary_points(sin(x), x, Interval(-sym_pi/2, sym_pi/2)) })), "{-pi/2, pi/2}")
  expect_identical(.pyrun(local({ x <- Symbol("x"); y <- Symbol("y"); stationary_points(sin(x), x, Interval(0, sym_pi/4, FALSE, TRUE)) })), "EmptySet")
  expect_identical(.pyrun(local({ x <- Symbol("x"); y <- Symbol("y"); stationary_points(tan(x), x) })), "EmptySet")
  expect_identical(.pyrun(local({ x <- Symbol("x"); y <- Symbol("y"); stationary_points((x+3)*(x-2), x) })), "{-1/2}")
  expect_identical(.pyrun(local({ x <- Symbol("x"); y <- Symbol("y"); stationary_points((x + 3)/(x - 2), x, Interval(-5, 5)) })), "EmptySet")
  expect_identical(.pyrun(local({ x <- Symbol("x"); y <- Symbol("y"); stationary_points((x^2+3)/(x-2), x) })), "{2 - sqrt(7), 2 + sqrt(7)}")
  expect_identical(.pyrun(local({ x <- Symbol("x"); y <- Symbol("y"); stationary_points((x^2+3)/(x-2), x, Interval(0, 5)) })), "{2 + sqrt(7)}")
  expect_identical(.pyrun(local({ x <- Symbol("x"); y <- Symbol("y"); stationary_points(x^4 + x^3 - 5*x^2, x, Reals) })), "{-2, 0, 5/4}")
  expect_identical(.pyrun(local({ x <- Symbol("x"); y <- Symbol("y"); stationary_points(exp(x), x) })), "EmptySet")
  expect_identical(.pyrun(local({ x <- Symbol("x"); y <- Symbol("y"); stationary_points(log(x) - x, x, Reals) })), "{1}")
  expect_identical(.pyrun(local({ x <- Symbol("x"); y <- Symbol("y"); stationary_points(y, x, Reals) })), "Reals")
  expect_identical(.pyrun(local({ x <- Symbol("x"); y <- Symbol("y"); stationary_points(y, x, EmptySet) })), "EmptySet")
})

test_that("monotonicity_helper: mono matches SymPy", {
  expect_identical(.pyrun(local({ x <- Symbol("x"); y <- Symbol("y"); monotonicity_helper(x^3 - 3*x^2 + 4*x, function(d) Ge(d, 0), Reals) })), "True")
  expect_identical(.pyrun(local({ x <- Symbol("x"); y <- Symbol("y"); monotonicity_helper(x^3 - 3*x^2 + 4*x, function(d) Gt(d, 0), Reals) })), "True")
  expect_identical(.pyrun(local({ x <- Symbol("x"); y <- Symbol("y"); monotonicity_helper(x^3 - 3*x^2 + 4*x, function(d) Le(d, 0), Reals) })), "False")
  expect_identical(.pyrun(local({ x <- Symbol("x"); y <- Symbol("y"); monotonicity_helper(x^3 - 3*x^2 + 4*x, function(d) Lt(d, 0), Reals) })), "False")
  expect_identical(.pyrun(local({ x <- Symbol("x"); y <- Symbol("y"); monotonicity_helper(-x^2, function(d) Ge(d, 0), Interval(-oo, 0)) })), "True")
  expect_identical(.pyrun(local({ x <- Symbol("x"); y <- Symbol("y"); monotonicity_helper(-x^2, function(d) Gt(d, 0), Interval(-oo, 0)) })), "False")
  expect_identical(.pyrun(local({ x <- Symbol("x"); y <- Symbol("y"); monotonicity_helper(-x^2, function(d) Le(d, 0), Interval(-oo, 0)) })), "False")
  expect_identical(.pyrun(local({ x <- Symbol("x"); y <- Symbol("y"); monotonicity_helper(-x^2, function(d) Lt(d, 0), Interval(-oo, 0)) })), "False")
  expect_identical(.pyrun(local({ x <- Symbol("x"); y <- Symbol("y"); monotonicity_helper(-x^2, function(d) Ge(d, 0), Interval(-oo, 1)) })), "False")
  expect_identical(.pyrun(local({ x <- Symbol("x"); y <- Symbol("y"); monotonicity_helper(-x^2, function(d) Gt(d, 0), Interval(-oo, 1)) })), "False")
  expect_identical(.pyrun(local({ x <- Symbol("x"); y <- Symbol("y"); monotonicity_helper(-x^2, function(d) Le(d, 0), Interval(-oo, 1)) })), "False")
  expect_identical(.pyrun(local({ x <- Symbol("x"); y <- Symbol("y"); monotonicity_helper(-x^2, function(d) Lt(d, 0), Interval(-oo, 1)) })), "False")
  expect_identical(.pyrun(local({ x <- Symbol("x"); y <- Symbol("y"); monotonicity_helper(4*x + 5, function(d) Ge(d, 0), Reals) })), "True")
  expect_identical(.pyrun(local({ x <- Symbol("x"); y <- Symbol("y"); monotonicity_helper(4*x + 5, function(d) Gt(d, 0), Reals) })), "True")
  expect_identical(.pyrun(local({ x <- Symbol("x"); y <- Symbol("y"); monotonicity_helper(4*x + 5, function(d) Le(d, 0), Reals) })), "False")
  expect_identical(.pyrun(local({ x <- Symbol("x"); y <- Symbol("y"); monotonicity_helper(4*x + 5, function(d) Lt(d, 0), Reals) })), "False")
  expect_identical(.pyrun(local({ x <- Symbol("x"); y <- Symbol("y"); monotonicity_helper(1/x, function(d) Ge(d, 0), Interval(0, oo)) })), "False")
  expect_identical(.pyrun(local({ x <- Symbol("x"); y <- Symbol("y"); monotonicity_helper(1/x, function(d) Gt(d, 0), Interval(0, oo)) })), "False")
  expect_identical(.pyrun(local({ x <- Symbol("x"); y <- Symbol("y"); monotonicity_helper(1/x, function(d) Le(d, 0), Interval(0, oo)) })), "None")
  expect_identical(.pyrun(local({ x <- Symbol("x"); y <- Symbol("y"); monotonicity_helper(1/x, function(d) Lt(d, 0), Interval(0, oo)) })), "None")
  expect_identical(.pyrun(local({ x <- Symbol("x"); y <- Symbol("y"); monotonicity_helper(1/x, function(d) Ge(d, 0), Interval(-2, 2)) })), "False")
  expect_identical(.pyrun(local({ x <- Symbol("x"); y <- Symbol("y"); monotonicity_helper(1/x, function(d) Gt(d, 0), Interval(-2, 2)) })), "False")
  expect_identical(.pyrun(local({ x <- Symbol("x"); y <- Symbol("y"); monotonicity_helper(1/x, function(d) Le(d, 0), Interval(-2, 2)) })), "False")
  expect_identical(.pyrun(local({ x <- Symbol("x"); y <- Symbol("y"); monotonicity_helper(1/x, function(d) Lt(d, 0), Interval(-2, 2)) })), "False")
  expect_identical(.pyrun(local({ x <- Symbol("x"); y <- Symbol("y"); monotonicity_helper(exp(x), function(d) Ge(d, 0), Reals) })), "True")
  expect_identical(.pyrun(local({ x <- Symbol("x"); y <- Symbol("y"); monotonicity_helper(exp(x), function(d) Gt(d, 0), Reals) })), "True")
  expect_identical(.pyrun(local({ x <- Symbol("x"); y <- Symbol("y"); monotonicity_helper(exp(x), function(d) Le(d, 0), Reals) })), "False")
  expect_identical(.pyrun(local({ x <- Symbol("x"); y <- Symbol("y"); monotonicity_helper(exp(x), function(d) Lt(d, 0), Reals) })), "False")
  expect_identical(.pyrun(local({ x <- Symbol("x"); y <- Symbol("y"); monotonicity_helper(log(x), function(d) Ge(d, 0), Interval(0, oo)) })), "False")
  expect_identical(.pyrun(local({ x <- Symbol("x"); y <- Symbol("y"); monotonicity_helper(log(x), function(d) Gt(d, 0), Interval(0, oo)) })), "False")
  expect_identical(.pyrun(local({ x <- Symbol("x"); y <- Symbol("y"); monotonicity_helper(log(x), function(d) Le(d, 0), Interval(0, oo)) })), "False")
  expect_identical(.pyrun(local({ x <- Symbol("x"); y <- Symbol("y"); monotonicity_helper(log(x), function(d) Lt(d, 0), Interval(0, oo)) })), "False")
  expect_identical(.pyrun(local({ x <- Symbol("x"); y <- Symbol("y"); monotonicity_helper(x^2, function(d) Ge(d, 0), Interval(0, 1)) })), "True")
  expect_identical(.pyrun(local({ x <- Symbol("x"); y <- Symbol("y"); monotonicity_helper(x^2, function(d) Gt(d, 0), Interval(0, 1)) })), "False")
  expect_identical(.pyrun(local({ x <- Symbol("x"); y <- Symbol("y"); monotonicity_helper(x^2, function(d) Le(d, 0), Interval(0, 1)) })), "False")
  expect_identical(.pyrun(local({ x <- Symbol("x"); y <- Symbol("y"); monotonicity_helper(x^2, function(d) Lt(d, 0), Interval(0, 1)) })), "False")
  expect_identical(.pyrun(local({ x <- Symbol("x"); y <- Symbol("y"); monotonicity_helper(cos(x), function(d) Ge(d, 0), Interval(0, sym_pi)) })), "False")
  expect_identical(.pyrun(local({ x <- Symbol("x"); y <- Symbol("y"); monotonicity_helper(cos(x), function(d) Gt(d, 0), Interval(0, sym_pi)) })), "False")
  expect_identical(.pyrun(local({ x <- Symbol("x"); y <- Symbol("y"); monotonicity_helper(cos(x), function(d) Le(d, 0), Interval(0, sym_pi)) })), "True")
  expect_identical(.pyrun(local({ x <- Symbol("x"); y <- Symbol("y"); monotonicity_helper(cos(x), function(d) Lt(d, 0), Interval(0, sym_pi)) })), "False")
  expect_identical(.pyrun(local({ x <- Symbol("x"); y <- Symbol("y"); monotonicity_helper(x^3, function(d) Ge(d, 0), Reals) })), "True")
  expect_identical(.pyrun(local({ x <- Symbol("x"); y <- Symbol("y"); monotonicity_helper(x^3, function(d) Gt(d, 0), Reals) })), "None")
  expect_identical(.pyrun(local({ x <- Symbol("x"); y <- Symbol("y"); monotonicity_helper(x^3, function(d) Le(d, 0), Reals) })), "False")
  expect_identical(.pyrun(local({ x <- Symbol("x"); y <- Symbol("y"); monotonicity_helper(x^3, function(d) Lt(d, 0), Reals) })), "False")
  expect_identical(.pyrun(local({ x <- Symbol("x"); y <- Symbol("y"); monotonicity_helper(y*x, function(d) Ge(d, 0), Reals) })), "ERR NotImplementedError: The function has not yet been implemented for all multivariate expressions.")
  expect_identical(.pyrun(local({ x <- Symbol("x"); y <- Symbol("y"); monotonicity_helper(y*x, function(d) Gt(d, 0), Reals) })), "ERR NotImplementedError: The function has not yet been implemented for all multivariate expressions.")
  expect_identical(.pyrun(local({ x <- Symbol("x"); y <- Symbol("y"); monotonicity_helper(y*x, function(d) Le(d, 0), Reals) })), "ERR NotImplementedError: The function has not yet been implemented for all multivariate expressions.")
  expect_identical(.pyrun(local({ x <- Symbol("x"); y <- Symbol("y"); monotonicity_helper(y*x, function(d) Lt(d, 0), Reals) })), "ERR NotImplementedError: The function has not yet been implemented for all multivariate expressions.")
  expect_identical(.pyrun(local({ x <- Symbol("x"); y <- Symbol("y"); monotonicity_helper(x^2 + y, function(d) Ge(d, 0), Interval(0, 1), x) })), "True")
  expect_identical(.pyrun(local({ x <- Symbol("x"); y <- Symbol("y"); monotonicity_helper(Integer(5), function(d) Ge(d, 0)) })), "True")
})

